// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        // admissible domain: valid receiver, positive amount
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));
        vm.assume(receiver.code.length == 0); // EOA: low-level transfer to it always succeeds
        vm.assume(amount > 0 && amount < type(uint128).max);

        // fund the contract so the transfer can succeed
        vm.deal(address(c), amount);

        uint256 recvBefore = receiver.balance;
        uint256 cBefore = address(c).balance;

        // msg.sender is this test contract == owner, so the call passes the guard
        c.sendTo(receiver, amount);

        // GENERAL RULE: after a successful sendTo, the receiver's balance grows
        // by exactly `amount` (funds leave the contract to the receiver).
        assertTrue(
            receiver.balance == recvBefore + amount && address(c).balance == cBefore - amount,
            "sendTo must transfer amount to the receiver"
        );
    }
}
